<?php $popularPlaces = ['Dar es Salaam', 'Zanzibar', 'Arusha']; $popularCheckIn = date('Y-m-d', strtotime('+7 days')); $popularCheckOut = date('Y-m-d', strtotime('+12 days')); ?><section class="fn-home-section fn-popular-searches"><div class="container fn-home-container"><div class="fn-section-heading fn-section-heading-row"><div><p class="fn-eyebrow">Explore Tanzania</p><h2>Popular searches</h2><p>Start with a destination and adjust the details to match your trip.</p></div><a class="fn-text-link" href="<?= $this->Url->build('/hotel-list-01') ?>">View all stays <i class="fa-solid fa-arrow-right"></i></a></div><div class="fn-popular-grid"><?php foreach ($popularPlaces as $place): ?><a class="fn-popular-link" href="<?= $this->Url->build('/hotel-list-01?destination=' . urlencode($place) . '&checkIn=' . $popularCheckIn . '&checkOut=' . $popularCheckOut . '&adults=2&rooms=1') ?>"><span><i class="fa-solid fa-location-dot"></i><?= h($place) ?></span><i class="fa-solid fa-chevron-right"></i></a><?php endforeach; ?></div></div></section>
